def is_reasonable_network(n, m, friendships):
    # Create a graph representation using adjacency list
    graph = {i: [] for i in range(1, n + 1)}
    for a, b in friendships:
        graph[a].append(b)
        graph[b].append(a)

    # Check for every triplet (X, Y, Z) if X-Y and Y-Z implies X-Z
    for x in range(1, n + 1):
        for y in graph[x]:
            for z in graph[y]:
                if z != x and z not in graph[x]:
                    return "NO"
    return "YES"

